var cascadingSlotGameResult=function(){var t=document.querySelector("#result-container"),i=document.querySelector("template"),n=0;return{addTumble:function(){var r=i.content.cloneNode(!0);r.querySelector("span").textContent=n===0?"Base Spin":"Tumbling "+n;t.appendChild(r);n++},submit:function(n){n.preventDefault()}}}();$(document).ready(function(){cascadingSlotGameResult.addTumble()});